.btn { font: 700 14px/1 'Monzo Sans', system-ui, sans-serif; border-radius: 9999px; padding: 14px 22px; border: 0; display: inline-flex; align-items: center; justify-content: center; gap: 8px; cursor: pointer; transition: background var(--duration-base) var(--ease-out), transform var(--duration-fast) var(--ease-out); }
.btn-primary { background: var(--color-primary-500); color: var(--text-on-primary); }
.btn-primary:hover { background: var(--color-primary-600); }
.btn-primary:active { transform: scale(0.97); }
.btn-secondary { background: var(--color-navy); color: var(--color-soft-white); border: 1.5px solid var(--border-strong); }
.btn-secondary:hover { background: var(--color-neutral-300); }
.btn-ghost { background: transparent; color: var(--color-primary-500); }
.btn-danger { background: var(--color-error-fg); color: #1A0B09; }
.btn-pot { background: var(--color-lime); color: var(--color-navy); }   /* 저축 Pots */
.btn:disabled { opacity: .42; cursor: not-allowed; transform: none; }
.btn[aria-busy="true"] { cursor: progress; }
.input { background: var(--bg-elevated); border: 1.5px solid var(--border-strong); border-radius: 14px; padding: 14px 16px; color: var(--text-primary); font: 400 15px/1.3 inherit; }
.input::placeholder { color: var(--text-tertiary); }
.input:focus { outline: none; border-color: var(--color-primary-500); box-shadow: 0 0 0 3px rgba(255,107,92,0.22); }
.input[aria-invalid="true"] { border-color: var(--color-error-fg); }
.input:disabled { background: var(--bg-subtle); color: var(--text-disabled); cursor: not-allowed; }
.card-account { background: var(--color-coral); color: var(--color-navy); border-radius: 20px; padding: 22px; min-height: 200px; display: flex; flex-direction: column; justify-content: space-between; box-shadow: var(--shadow-coral); }
.card-account .label { font: 600 11px/1 inherit; letter-spacing: 0.16em; text-transform: uppercase; opacity: 0.85; }
.card-account .balance { font: 700 36px/1 inherit; letter-spacing: -0.01em; font-variant-numeric: tabular-nums; margin-top: 12px; }
.pot { background: var(--bg-elevated); border: 1px solid var(--border-default); border-radius: 20px; padding: 18px; cursor: pointer; display: flex; flex-direction: column; gap: 8px; box-shadow: var(--shadow-sm); }
.pot .icon { width: 44px; height: 44px; border-radius: 50%; background: var(--color-lime); color: var(--color-navy); display: grid; place-items: center; font-size: 22px; }
.pot .name { font: 700 15px/1.3 inherit; color: var(--text-primary); }
.pot .amount { font: 700 22px/1 inherit; color: var(--text-primary); font-variant-numeric: tabular-nums; }
.pot .progress { height: 6px; background: var(--bg-subtle); border-radius: 9999px; overflow: hidden; }
.pot .progress .bar { height: 100%; background: var(--color-primary-500); border-radius: 9999px; }
.card { background: var(--bg-elevated); border-radius: 14px; padding: 18px; box-shadow: var(--shadow-sm); }
.card-outlined { background: transparent; border: 1px solid var(--border-default); }
.tag { padding: 4px 10px; border-radius: 9999px; font: 700 11px/1.4 inherit; letter-spacing: 0.02em; }
.tag-current   { background: var(--color-primary-50); color: var(--color-primary-700); }
.tag-pot       { background: color-mix(in srgb, var(--color-lime) 20%, transparent); color: var(--color-warning-fg); }
.tag-savings   { background: var(--color-success-bg); color: var(--color-success-fg); }
.tag-premium   { background: var(--color-primary-500); color: var(--text-on-primary); }
.tag-shared    { background: var(--color-info-bg); color: var(--color-info-fg); }
.tab-bar { display: flex; gap: 16px; padding: 12px 16px; background: var(--bg-elevated); border-top: 1px solid var(--border-default); }
.tab-bar .tab { flex: 1; display: flex; flex-direction: column; align-items: center; gap: 4px; font: 600 11px/1.2 inherit; color: var(--text-tertiary); cursor: pointer; }
.tab-bar .tab.active { color: var(--color-primary-500); }
.tab-bar .tab .ic { font-size: 22px; }
